function Product () {
    const{id, category} =useParams()
    const {product, setProduct} =useState()
    useEffect(()=>{
        fetch('https://dummyjson.com/products')
    })
    return(
        <div>
            <p> Hello {category} {id}</p>
        </div>
    )
}

export default Product
